#!/usr/bin/env node
/**
 * assets/brand/songnook-mark.svg → every raster the app, the stores and the
 * splash need. The SVG is the master; the PNGs are build output. Change the
 * mark there, run `npm run brand:render`, commit both.
 *
 * Renders with headless Chrome (macOS path by default; set CHROME to override),
 * so it needs no npm dependency. Native folders are generated by prebuild from
 * app.json, so these PNGs are all the platforms read.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const chrome = process.env.CHROME ?? "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
if (!existsSync(chrome)) throw new Error(`Chrome not found at ${chrome}; set CHROME to its binary.`);

const PAPER = "#FDFBF7"; // colors.page
const TERRACOTTA = "#B87D6B"; // colors.primary
const INK = "#1b1c1a"; // colors.textPrimary
const SECONDARY = "#84736f"; // colors.textSecondary

// The mark fills 77 of the SVG's 120 units across (64%); `box` below is the SVG's
// rendered size, so the mark's own width is box × 0.64.
const svg = readFileSync(join(root, "assets/brand/songnook-mark.svg"), "utf8").replace(/<!--[\s\S]*?-->/g, "");
const markSvg = (box, extra = "") => svg.replace("<svg ", `<svg style="width:${box}px;height:${box}px;flex:none;${extra}" `);
// One-colour mark (white on terracotta for the lock screen).
const monoSvg = (box, color, extra) =>
  markSvg(box, extra).replace(/(fill|stroke)="#[0-9A-Fa-f]{6}"/g, `$1="${color}"`);

const work = mkdtempSync(join(tmpdir(), "songnook-brand-"));
const fontDir = join(root, "node_modules/@expo-google-fonts");

function render(out, { w, h, background, body, transparent = false }) {
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>
@font-face{font-family:Lora;src:url("file://${fontDir}/lora/600SemiBold/Lora_600SemiBold.ttf")}
@font-face{font-family:Jakarta;src:url("file://${fontDir}/plus-jakarta-sans/500Medium/PlusJakartaSans_500Medium.ttf")}
html,body{margin:0;width:${w}px;height:${h}px;overflow:hidden;background:${transparent ? "transparent" : background}}
.c{position:relative;width:${w}px;height:${h}px;display:flex;align-items:center;justify-content:center}
</style></head><body><div class="c">${body}</div></body></html>`;
  const page = join(work, `${out.replace(/\W/g, "_")}.html`);
  writeFileSync(page, html);
  const target = join(root, out);
  execFileSync(chrome, [
    "--headless=new", "--disable-gpu", "--hide-scrollbars", "--force-device-scale-factor=1",
    "--allow-file-access-from-files",
    ...(transparent ? ["--default-background-color=00000000"] : []),
    `--window-size=${w},${h}`, `--screenshot=${target}`, `file://${page}`,
  ], { stdio: "ignore" });
  console.log(`  ${out} (${w}×${h})`);
  return target;
}

console.log("Rendering from assets/brand/songnook-mark.svg");

// App icon (iOS + store): paper, full bleed, no rounded corners (the OS masks).
render("assets/icon.png", { w: 1024, h: 1024, background: PAPER, body: markSvg(1024) });
// Android adaptive foreground: the mark inside the 66% safe circle, background
// colour comes from app.json (adaptiveIcon.backgroundColor = paper).
render("assets/adaptive-icon.png", { w: 1024, h: 1024, transparent: true, body: markSvg(672) });
// Splash: shown "contain" on paper; the mark at about 30% of the image.
render("assets/splash-icon.png", { w: 1024, h: 1024, transparent: true, body: markSvg(480) });
// In-app mark (About colophon, welcome tour): close crop, 4× its 120 pt use.
render("assets/brand-mark.png", { w: 480, h: 480, transparent: true, body: markSvg(645) });
// Web favicon.
render("assets/favicon.png", { w: 64, h: 64, background: PAPER, body: markSvg(80) });
// Lock-screen / now-playing artwork: terracotta, paper mark bottom right.
render("assets/lock-screen-artwork.png", {
  w: 1024, h: 1024, background: TERRACOTTA,
  body: monoSvg(320, PAPER, "position:absolute;right:15px;bottom:-47px"),
});

// Store graphics.
render("docs/store-assets/play/icon-512.png", { w: 512, h: 512, background: PAPER, body: markSvg(512) });
render("docs/store-assets/play/feature-graphic-1024x500.png", {
  w: 1024, h: 500, background: PAPER,
  body: `<div style="display:flex;align-items:center;gap:8px">${markSvg(330, "margin:0 -20px 0 -40px")}
<div><div style="font-family:Lora;font-size:96px;line-height:1;color:${INK};letter-spacing:-1px;margin-bottom:18px">SongNook</div>
<div style="font-family:Jakarta;font-size:28px;line-height:1.35;color:${SECONDARY}">A quiet corner to<br>finish your songs.</div></div></div>`,
});

// Apple rejects an app icon with an alpha channel; Chrome writes RGBA, so flatten
// the opaque ones through JPEG at full quality and back.
for (const out of ["assets/icon.png", "docs/store-assets/play/icon-512.png", "assets/lock-screen-artwork.png", "assets/favicon.png"]) {
  const p = join(root, out);
  const jpg = join(work, "flat.jpg");
  execFileSync("sips", ["-s", "format", "jpeg", "-s", "formatOptions", "100", p, "--out", jpg], { stdio: "ignore" });
  execFileSync("sips", ["-s", "format", "png", jpg, "--out", p], { stdio: "ignore" });
}
console.log("Done.");
